// ── CF-01BE: NORMALIZE EVOLUTION → ENVELOPE JSON ────────────────────
//
// Payload real verificado (2026-03-13):
// {
//   body: {
//     event: 'messages.upsert',
//     instance: 'cfwa3',
//     data: {
//       key: {
//         remoteJid: '{{REDACTED:PHONE}}@s.whatsapp.net',  ← quien escribe
//         fromMe: false,
//         id: 'ACF497EECAA484FBE66AE29E3A596EC',
//         addressingMode: 'lid'
//       },
//       pushName: 'RR',
//       message: { conversation: 'Hola' },
//       messageType: 'conversation',
//       messageTimestamp: 1773441983,
//       instanceId: '1f62e380-...',
//       source: 'android'
//     },
//     sender: '{{REDACTED:PHONE}}@s.whatsapp.net',  ← número PROPIO de la instancia (ignorar)
//     server_url: 'http://localhost:8080',
//     apikey: '...'
//   }
// }

const body = $input.first().json._raw_body;
const data = body.data;
const key  = data.key;

// ── from_wa: número del paciente que escribe ─────────────────────────
// remoteJid = '{{REDACTED:PHONE}}@s.whatsapp.net' → extraer solo el número
const from_wa = key.remoteJid
  .replace(/@s\.whatsapp\.net$/, '')
  .replace(/@lid$/, '')
  .replace(/@.*$/, '');

// ── evo_instance: identifica al tenant ──────────────────────────────
// body.instance = 'cfwa3'
const evo_instance = body.instance;

// ── message_id ──────────────────────────────────────────────────────
const message_id = key.id;

// ── timestamp ───────────────────────────────────────────────────────
const ts = data.messageTimestamp ?? Math.floor(Date.now() / 1000);
const timestamp = new Date(ts * 1000).toISOString();

// ── nombre del contacto ─────────────────────────────────────────────
const wa_name = data.pushName ?? null;

// ── tipo y texto del mensaje ─────────────────────────────────────────
const msgType = data.messageType ?? 'unknown';
const msgObj  = data.message ?? {};

let text = null;
let msg_type_normalized = 'unknown';

switch (msgType) {
  case 'conversation':
    text = msgObj.conversation?.trim() ?? null;
    msg_type_normalized = 'text';
    break;
  case 'extendedTextMessage':
    text = msgObj.extendedTextMessage?.text?.trim() ?? null;
    msg_type_normalized = 'text';
    break;
  case 'imageMessage':
    msg_type_normalized = 'image';
    break;
  case 'audioMessage':
  case 'pttMessage':
    msg_type_normalized = 'audio';
    break;
  case 'documentMessage':
    msg_type_normalized = 'document';
    break;
  case 'buttonsResponseMessage':
  case 'listResponseMessage':
  case 'templateButtonReplyMessage':
    msg_type_normalized = 'interactive';
    break;
  default:
    msg_type_normalized = 'unknown';
}

// ── payload interactivo (botones / listas) ────────────────────────────
let interactive = { kind: null, id: null, title: null };

if (msgType === 'buttonsResponseMessage') {
  const btn = msgObj.buttonsResponseMessage;
  interactive = {
    kind:  'button_reply',
    id:    btn?.selectedButtonId ?? null,
    title: btn?.selectedDisplayText ?? null
  };
} else if (msgType === 'listResponseMessage') {
  const lst = msgObj.listResponseMessage;
  interactive = {
    kind:  'list_reply',
    id:    lst?.singleSelectReply?.selectedRowId ?? null,
    title: lst?.title ?? null
  };
} else if (msgType === 'templateButtonReplyMessage') {
  const tpl = msgObj.templateButtonReplyMessage;
  interactive = {
    kind:  'button_reply',
    id:    tpl?.selectedId ?? null,
    title: tpl?.selectedDisplayText ?? null
  };
}

// ── Envelope JSON — contrato estándar ClinicFlow ──────────────────────
// Idéntico al que produce CF-01B (Meta).
// Todo lo que viene después (CF-02 en adelante) trabaja sobre este contrato.
const envelope = {
  tenant: {
    tenant_id:          null,          // CF-02 lo resuelve
    wa_phone_number_id: null,          // no aplica con Evolution
    evo_instance_name:  evo_instance,  // CF-02 usa este campo para buscar tenant
    calendar_id:        null,
    timezone:           'America/Mexico_City',
    name:               null,
    settings:           {}
  },
  user: {
    wa_number: from_wa,
    wa_name:   wa_name,
    user_id:   null                    // CF-04 lo resuelve
  },
  patient: {
    active_patient_id: null            // CF-07 lo resuelve
  },
  session: {
    session_id:         null,
    current_step:       'idle',
    is_expired:         false,
    active_service_id:  null,
    pending_slot_start: null,
    pending_slot_end:   null,
    pending_context:    {}
  },
  message: {
    message_id:  message_id,
    timestamp:   timestamp,
    type:        msg_type_normalized,
    text:        text,
    interactive: interactive
  },
  routing: {
    intent:     null,
    confidence: null,
    source:     null
  },
  _channel: 'evolution',
  meta: {
    raw: body
  }
};

return [{ json: envelope }];
